// Minimal slices of the Unicode character database that CPython relies on.
//
// * `Py_UNICODE_ISSPACE` -- the charset used by `str.strip()`/`str.rstrip()`
//   with no argument, and by `int()` when it trims its operand.
// * category Nd (decimal digits) plus each digit's numeric value, used by
//   `int()` to accept e.g. Arabic-Indic or fullwidth digits.
// * `Py_UNICODE_ISPRINTABLE`, used by `repr()` of a str.

// Exactly the code points for which CPython's Py_UNICODE_ISSPACE is true.
const SPACE_SET = new Set([
  0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x1c, 0x1d, 0x1e, 0x1f, 0x20,
  0x85, 0xa0, 0x1680,
  0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005, 0x2006, 0x2007,
  0x2008, 0x2009, 0x200a,
  0x2028, 0x2029, 0x202f, 0x205f, 0x3000,
]);

export function isPySpace(cp) {
  return SPACE_SET.has(cp);
}

// Start code point of every 10-long run of category-Nd characters.  Every Nd
// block in the UCD is exactly ten consecutive code points whose numeric values
// run 0..9, so `cp - start` is the digit value.
const ND_STARTS = [
  48, 1632, 1776, 1984, 2406, 2534, 2662, 2790, 2918, 3046, 3174, 3302,
  3430, 3558, 3664, 3792, 3872, 4160, 4240, 6112, 6160, 6470, 6608, 6784,
  6800, 6992, 7088, 7232, 7248, 42528, 43216, 43264, 43472, 43504, 43600,
  44016, 65296, 66720, 68912, 69734, 69872, 69942, 70096, 70384, 70736,
  70864, 71248, 71360, 71472, 71904, 72016, 72784, 73040, 73120, 73552,
  92768, 92864, 93008, 120782, 120792, 120802, 120812, 120822, 123200,
  123632, 124144, 125264, 130032,
];

// Numeric value 0..9 of a decimal digit code point, or -1 when `cp` is not Nd.
export function decimalValue(cp) {
  let lo = 0;
  let hi = ND_STARTS.length - 1;
  let best = -1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (ND_STARTS[mid] <= cp) {
      best = ND_STARTS[mid];
      lo = mid + 1;
    } else {
      hi = mid - 1;
    }
  }
  if (best < 0) return -1;
  const delta = cp - best;
  return delta < 10 ? delta : -1;
}

const NONPRINTABLE = /[\p{C}\p{Zl}\p{Zp}\p{Zs}]/u;

// CPython: everything in Cc, Cf, Cs, Co, Cn, Zl, Zp, Zs is non-printable,
// except U+0020 which is deliberately treated as printable.
export function isPrintable(cp) {
  if (cp === 0x20) return true;
  if (cp >= 0xd800 && cp <= 0xdfff) return false;
  return !NONPRINTABLE.test(String.fromCodePoint(cp));
}

// Primitives for Python-style byte strings, modelled as plain Arrays of
// integers in 0..255.

export function concat(a, b) {
  const out = a.slice();
  for (let i = 0; i < b.length; i++) out.push(b[i]);
  return out;
}

export function equal(a, b) {
  if (a.length !== b.length) return false;
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false;
  return true;
}

// Python `bytes[start:]`-style slice with negative index support.
export function slice(a, start, stop) {
  const n = a.length;
  let s = start === undefined ? 0 : start;
  let e = stop === undefined ? n : stop;
  if (s < 0) s += n;
  if (e < 0) e += n;
  if (s < 0) s = 0;
  if (e > n) e = n;
  if (e < s) e = s;
  return a.slice(s, e);
}

// Python `bytes.lstrip(single_byte)`.
export function lstripByte(a, byte) {
  let i = 0;
  while (i < a.length && a[i] === byte) i++;
  return a.slice(i);
}

// Python `bytes.rstrip()` with no argument: ASCII whitespace only
// (space, \t, \n, \v, \f, \r).
const ASCII_SPACE = new Set([0x20, 0x09, 0x0a, 0x0b, 0x0c, 0x0d]);

export function rstripAsciiSpace(a) {
  let end = a.length;
  while (end > 0 && ASCII_SPACE.has(a[end - 1])) end--;
  return a.slice(0, end);
}

export function repeatByte(byte, count) {
  const out = [];
  for (let i = 0; i < count; i++) out.push(byte);
  return out;
}

// Python `int.from_bytes(v, 'big')`.
export function intFromBytesBig(a) {
  let acc = 0n;
  for (let i = 0; i < a.length; i++) acc = (acc << 8n) | BigInt(a[i]);
  return acc;
}

// Bytes of an all-ASCII JS string, without validation.
export function fromAsciiLiteral(s) {
  const out = [];
  for (let i = 0; i < s.length; i++) out.push(s.charCodeAt(i) & 0xff);
  return out;
}

// Interpret a byte string as latin-1 text (only used to build JS strings out of
// pure-ASCII base58 output for printing).
export function toLatin1String(a) {
  let s = '';
  for (let i = 0; i < a.length; i++) s += String.fromCharCode(a[i]);
  return s;
}

// Python exception analogues plus the traceback rendering used by the frozen
// (PyInstaller) reference build.

function hex(n, width) {
  let s = n.toString(16);
  while (s.length < width) s = '0' + s;
  return s;
}

export class PyException extends Error {
  constructor(typeName, message) {
    super(`${typeName}: ${message}`);
    this.typeName = typeName;
    this.pyMessage = message;
    // Outermost frame first, matching the order Python prints them.
    this.frames = [];
  }

  exceptionLine() {
    return `${this.typeName}: ${this.pyMessage}`;
  }
}

export class PyValueError extends PyException {
  constructor(message) {
    super('ValueError', message);
  }
}

// Mirrors CPython's UnicodeEncodeError.__str__: a single offending code point
// is rendered with its \x/\u/\U escape, a run collapses to "characters in
// position start-end".
export function formatEncodeError(encoding, codePoints, start, end, reason) {
  if (start < codePoints.length && end === start + 1) {
    const bad = codePoints[start];
    let esc;
    if (bad <= 0xff) esc = '\\x' + hex(bad, 2);
    else if (bad <= 0xffff) esc = '\\u' + hex(bad, 4);
    else esc = '\\U' + hex(bad, 8);
    return `'${encoding}' codec can't encode character '${esc}' in position ${start}: ${reason}`;
  }
  return `'${encoding}' codec can't encode characters in position ${start}-${end - 1}: ${reason}`;
}

export class PyUnicodeEncodeError extends PyException {
  constructor(encoding, codePoints, start, end, reason) {
    super('UnicodeEncodeError', formatEncodeError(encoding, codePoints, start, end, reason));
    this.encoding = encoding;
    this.start = start;
    this.end = end;
    this.reason = reason;
  }
}

export function withFrames(err, frames) {
  err.frames = frames.concat(err.frames);
  return err;
}

export function formatTraceback(err) {
  let out = 'Traceback (most recent call last):\n';
  for (const f of err.frames) {
    out += `  File "${f.file}", line ${f.line}, in ${f.name}\n`;
  }
  out += err.exceptionLine() + '\n';
  return out;
}

// UTF-8 / ASCII codecs with CPython semantics, including the
// `surrogateescape` and `replace` error handlers.
//
// A Python `str` is modelled as a JS string; because lone surrogates matter
// here, positions are always counted in code points via `codePoints()`.

import { PyUnicodeEncodeError } from './pyerrors.mjs';

// Split a JS string into code points.  Unpaired surrogates survive as their own
// single-unit entries, which is exactly what `surrogateescape` produces.
export function codePoints(s) {
  const out = [];
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    if (c >= 0xd800 && c <= 0xdbff && i + 1 < s.length) {
      const d = s.charCodeAt(i + 1);
      if (d >= 0xdc00 && d <= 0xdfff) {
        out.push(0x10000 + ((c - 0xd800) << 10) + (d - 0xdc00));
        i++;
        continue;
      }
    }
    out.push(c);
  }
  return out;
}

export function fromCodePoints(cps) {
  let s = '';
  for (let i = 0; i < cps.length; i++) {
    const cp = cps[i];
    if (cp >= 0xd800 && cp <= 0xdfff) s += String.fromCharCode(cp);
    else s += String.fromCodePoint(cp);
  }
  return s;
}

function isSurrogate(cp) {
  return cp >= 0xd800 && cp <= 0xdfff;
}

// Python `str.encode()` (utf-8, strict).  Lone surrogates raise, and adjacent
// bad code points are reported as one range.
export function encodeUtf8(s) {
  const cps = codePoints(s);
  const out = [];
  for (let i = 0; i < cps.length; i++) {
    const cp = cps[i];
    if (cp < 0x80) {
      out.push(cp);
    } else if (cp < 0x800) {
      out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    } else if (isSurrogate(cp)) {
      let end = i + 1;
      while (end < cps.length && isSurrogate(cps[end])) end++;
      throw new PyUnicodeEncodeError('utf-8', cps, i, end, 'surrogates not allowed');
    } else if (cp < 0x10000) {
      out.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
    } else {
      out.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3f),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f),
      );
    }
  }
  return out;
}

// Python `str.encode('ascii')` (strict).
export function encodeAscii(s) {
  const cps = codePoints(s);
  const out = [];
  for (let i = 0; i < cps.length; i++) {
    const cp = cps[i];
    if (cp < 0x80) {
      out.push(cp);
      continue;
    }
    let end = i + 1;
    while (end < cps.length && cps[end] >= 0x80) end++;
    throw new PyUnicodeEncodeError('ascii', cps, i, end, 'ordinal not in range(128)');
  }
  return out;
}

// Shared UTF-8 decoder.  On malformed input it reports the "maximal subpart"
// (the longest prefix of a would-be sequence), which is how both CPython and
// V8 group decoding errors.
function decodeUtf8(bytes, emitChar, emitError) {
  const n = bytes.length;
  let i = 0;
  while (i < n) {
    const b0 = bytes[i];
    if (b0 < 0x80) {
      emitChar(b0);
      i++;
      continue;
    }
    let need = 0;
    let lo = 0x80;
    let hi = 0xbf;
    let acc = 0;
    if (b0 >= 0xc2 && b0 <= 0xdf) {
      need = 1;
      acc = b0 & 0x1f;
    } else if (b0 >= 0xe0 && b0 <= 0xef) {
      need = 2;
      acc = b0 & 0x0f;
      if (b0 === 0xe0) lo = 0xa0;
      else if (b0 === 0xed) hi = 0x9f;
    } else if (b0 >= 0xf0 && b0 <= 0xf4) {
      need = 3;
      acc = b0 & 0x07;
      if (b0 === 0xf0) lo = 0x90;
      else if (b0 === 0xf4) hi = 0x8f;
    } else {
      emitError([b0]);
      i++;
      continue;
    }
    let j = i + 1;
    let ok = true;
    for (let k = 0; k < need; k++) {
      const min = k === 0 ? lo : 0x80;
      const max = k === 0 ? hi : 0xbf;
      if (j >= n) {
        ok = false;
        break;
      }
      const b = bytes[j];
      if (b < min || b > max) {
        ok = false;
        break;
      }
      acc = (acc << 6) | (b & 0x3f);
      j++;
    }
    if (!ok) {
      emitError(bytes.slice(i, j));
      i = j;
      continue;
    }
    emitChar(acc);
    i = j;
  }
}

// Python `bytes.decode('utf-8', 'surrogateescape')`: each undecodable byte
// becomes U+DC00+byte.
export function decodeUtf8Surrogateescape(bytes) {
  const cps = [];
  decodeUtf8(
    bytes,
    (cp) => cps.push(cp),
    (bad) => {
      for (let i = 0; i < bad.length; i++) cps.push(0xdc00 + bad[i]);
    },
  );
  return fromCodePoints(cps);
}

// Python `bytes.decode('utf-8', 'replace')`: one U+FFFD per maximal subpart.
// Used only to cross-check our recovered argv against `process.argv`.
export function decodeUtf8Replace(bytes) {
  const cps = [];
  decodeUtf8(
    bytes,
    (cp) => cps.push(cp),
    () => cps.push(0xfffd),
  );
  return fromCodePoints(cps);
}

// Python `repr()` for `bytes` and `str`.

import { codePoints } from './pycodec.mjs';
import { isPrintable } from './unidata.mjs';

const SQ = 0x27; // '
const DQ = 0x22; // "
const BS = 0x5c; // \

function hex(n, width) {
  let s = n.toString(16);
  while (s.length < width) s = '0' + s;
  return s;
}

function pickQuote(units) {
  let hasSingle = false;
  let hasDouble = false;
  for (let i = 0; i < units.length; i++) {
    if (units[i] === SQ) hasSingle = true;
    else if (units[i] === DQ) hasDouble = true;
  }
  return hasSingle && !hasDouble ? DQ : SQ;
}

// repr(b'...')
export function bytesRepr(bytes) {
  const quote = pickQuote(bytes);
  let out = 'b' + String.fromCharCode(quote);
  for (let i = 0; i < bytes.length; i++) {
    const c = bytes[i];
    if (c === quote || c === BS) out += '\\' + String.fromCharCode(c);
    else if (c === 0x09) out += '\\t';
    else if (c === 0x0a) out += '\\n';
    else if (c === 0x0d) out += '\\r';
    else if (c < 0x20 || c >= 0x7f) out += '\\x' + hex(c, 2);
    else out += String.fromCharCode(c);
  }
  return out + String.fromCharCode(quote);
}

// repr('...')
export function strRepr(s) {
  const cps = codePoints(s);
  const quote = pickQuote(cps);
  let out = String.fromCharCode(quote);
  for (let i = 0; i < cps.length; i++) {
    const c = cps[i];
    if (c === quote || c === BS) out += '\\' + String.fromCharCode(c);
    else if (c === 0x09) out += '\\t';
    else if (c === 0x0a) out += '\\n';
    else if (c === 0x0d) out += '\\r';
    else if (c < 0x20 || c === 0x7f) out += '\\x' + hex(c, 2);
    else if (c < 0x7f) out += String.fromCharCode(c);
    else if (isPrintable(c)) out += String.fromCodePoint(c);
    else if (c <= 0xff) out += '\\x' + hex(c, 2);
    else if (c <= 0xffff) out += '\\u' + hex(c, 4);
    else out += '\\U' + hex(c, 8);
  }
  return out + String.fromCharCode(quote);
}

// Python `str.rstrip()` with no argument: strips the Unicode whitespace set.

import { codePoints, fromCodePoints } from './pycodec.mjs';
import { isPySpace } from './unidata.mjs';

export function rstrip(s) {
  const cps = codePoints(s);
  let end = cps.length;
  while (end > 0 && isPySpace(cps[end - 1])) end--;
  return end === cps.length ? s : fromCodePoints(cps.slice(0, end));
}

// Python's `int(str)` for base 10.
//
// CPython first runs _PyUnicode_TransformDecimalAndSpaceToASCII, which folds
// every Unicode-whitespace code point to U+0020 and every category-Nd digit to
// its ASCII counterpart, then hands the result to the ASCII integer parser.

import { codePoints } from './pycodec.mjs';
import { decimalValue, isPySpace } from './unidata.mjs';

export class IntParseError extends Error {}

// Digits, optionally separated by single underscores that must sit between
// digits.  This encodes "no leading/trailing/doubled underscore" in one place.
const DIGITS = /^[0-9](?:_?[0-9])*$/;

export function pyInt(s) {
  const cps = codePoints(s);
  let ascii = '';
  for (let i = 0; i < cps.length; i++) {
    const cp = cps[i];
    if (isPySpace(cp)) {
      ascii += ' ';
      continue;
    }
    const d = decimalValue(cp);
    if (d >= 0) {
      ascii += String(d);
      continue;
    }
    // Anything else is passed through verbatim and will be rejected below
    // (unless it is '+', '-' or '_').
    ascii += cp < 0x80 ? String.fromCharCode(cp) : '�';
