  // Leading / trailing ASCII whitespace is ignored.
  body = body.replace(/^[ \t\n\v\f\r]+/, '').replace(/[ \t\n\v\f\r]+$/, '');

  let negative = false;
  if (body.startsWith('+')) body = body.slice(1);
  else if (body.startsWith('-')) {
    negative = true;
    body = body.slice(1);
  }

  if (!DIGITS.test(body)) throw new IntParseError('invalid literal');

  const value = BigInt(body.replace(/_/g, ''));
  return negative ? -value : value;
