import { codePoints } from './pycodec.mjs';
import { decimalValue, isPySpace } from './unidata.mjs';

export class IntParseError extends Error {}

// Digits, optionally separated by single underscores that must sit between
// digits.  This encodes "no leading/trailing/doubled underscore" in one place.
const DIGITS = /^[0-9](?:_?[0-9])*$/;

export function pyInt(s) {
  const cps = codePoints(s);
  let folded = '';
  for (let i = 0; i < cps.length; i++) {
    const cp = cps[i];
    if (isPySpace(cp)) {
      folded += ' ';
      continue;
    }
    const d = decimalValue(cp);
    if (d >= 0) {
      folded += String(d);
      continue;
    }
    // Everything else survives untouched and will be rejected below, unless it
    // is a sign or an underscore.
    if (cp >= 0xd800 && cp <= 0xdfff) folded += String.fromCharCode(cp);
    else folded += String.fromCodePoint(cp);
  }

  // Leading / trailing ASCII whitespace is ignored by the integer parser.
  let body = folded.replace(/^[ \t\n\v\f\r]+/, '').replace(/[ \t\n\v\f\r]+$/, '');

  let negative = false;
  if (body.startsWith('+')) {
    body = body.slice(1);
  } else if (body.startsWith('-')) {
    negative = true;
    body = body.slice(1);
  }

  if (!DIGITS.test(body)) throw new IntParseError('invalid literal');

  const value = BigInt(body.replace(/_/g, ''));
  return negative ? -value : value;
}

// argparse's `_negative_number_matcher`, i.e. r'^-\d+$|^-\d*\.\d+$' with
// Python's Unicode-aware \d (= category Nd).
export function looksLikeNegativeNumber(s) {
  const cps = codePoints(s);
  if (cps.length < 2 || cps[0] !== 0x2d) return false;
  let shape = '';
  for (let i = 1; i < cps.length; i++) {
    if (decimalValue(cps[i]) >= 0) shape += 'd';
    else if (cps[i] === 0x2e) shape += '.';
    else return false;
  }
  return /^d+$/.test(shape) || /^d*\.d+$/.test(shape);
}

